+
+// requireOperatorScope is the shared opening of an approval-class operator
+// handler: an authenticated identity holding scope. It writes the refusal
+// and returns false when the caller may not proceed.
+func (s *Server) requireOperatorScope(w http.ResponseWriter, r *http.Request, id Identity, scope string) bool {
+	if id.IsAnonymous() {
+		s.writeError(w, r, http.StatusUnauthorized, "authentication_required",
+			"an authenticated token is required", nil)
+		return false
+	}
+	if !hasScope(id, scope) {
+		s.writeError(w, r, http.StatusForbidden, "insufficient_scope",
+			"token is missing required scope: "+scope,
+			map[string]any{"required_scope": scope})
+		return false
+	}
+	return true
+}
